request.description:
### Send a customer's information to EI to get an auto insurance quote for them in the portal.

Annotated example payload:

``` json
{
  // Required: Main applicant information
  "applicant": {
    "firstName": "John",
    "lastName": "Doe",
    "dateOfBirth": "1980-01-01", // Format: YYYY-MM-DD
    "address": {
      "address1": "123 Main St",
      "address2": "Apt 4B", // Optional
      "city": "Boston",
      "state": "MA", // 2 letter US state abbreviation
      "zip": "02108" // 5 digit US ZIP code
    },
    "phoneNumber": "+16175551234", // leading +1 then 10 digits phone number
    "email": "john@example.com",
    // Optional fields below
    "monthsAtAddress": 24,
    "priorAddress": {
      "address1": "456 Old St",
      "city": "Cambridge",
      "state": "MA",
      "zip": "02139"
    },
    "gender": "Male", // Optional: "Male" | "Female" | "Non-Binary"
    "licenseNumber": "S12345678", // Optional
    "licenseState": "MA", // Optional
    "yearsLicensed": 15, // Optional
    "educationLevel": "BachelorsDegree", // Optional: 'LessThanHighSchoolDiploma', 'HighSchool', 'SomeCollegeNoDegree', 'AssociateDegree', 'BachelorsDegree', 'MastersDegree', 'PostGraduate', 'DoctorMedicine', 'LawDegree', 'VocationalTechnical'
    "residenceOwnershipType": "Own", // Optional: "Rent" | "Own" | "Other"
    "maritalStatus": "Married", // Optional: "Single" | "Married" | "Divorced" | "Widowed" | "Seperated" | "Domestic Partner"
    // Optional: Array of income sources
    "income": [
      {
        "employmentType": "Full-Time", // Optional: 'Full-Time', 'Part-Time', 'Self-Employed', 'Contractor', 'Active-Military', 'Other'
        "employerName": "Tech Corp", // Optional: string
        "jobTitle": "Engineer", // Optional: string
        "monthsAtEmployer": 36, // Optional
        "annualIncome": "120000" // Optional, in dollars
      }
    ],
    "creditIndicator": "800" // Optional, a credit indicator
  },
  // Optional: Co-applicant(s)
  "coapplicants": {
  // Keys must be 1-9
    "1": {
      "firstName": "Jane",
      "lastName": "Doe",
      "dateOfBirth": "1982-02-02", // Format: YYYY-MM-DD
      // Optional fields below
      "phoneNumber": "+16175559876", // leading +1 then 10 digits phone number
      "email": "jane@example.com",
      "relationshipToApplicant": "Spouse", // "Spouse" | "Parent" | "Child" | "Relative" | "Cohabitant" | "Other"
      "gender": "Female", // Optional: "Male" | "Female" | "Non-Binary"
      "licenseNumber": "S87654321", // Optional
      "licenseState": "MA", // Optional
      "yearsLicensed": 12, // Optional
      "educationLevel": "MastersDegree", // Optional: 'LessThanHighSchoolDiploma', 'HighSchool', 'SomeCollegeNoDegree', 'AssociateDegree', 'BachelorsDegree', 'MastersDegree', 'PostGraduate', 'DoctorMedicine', 'LawDegree', 'VocationalTechnical'
      "maritalStatus": "Married", // Optional: "Single" | "Married" | "Divorced" | "Widowed" | "Seperated" | "Domestic Partner"
      // Optional: Array of income sources
      "income": [
        {
          "employmentType": "Part-Time", // Optional: 'Full-Time', 'Part-Time', 'Self-Employed', 'Contractor', 'Active-Military', 'Other'
          "employerName": "Education Corp", // Optional: string
          "jobTitle": "Teacher", // Optional: string
          "monthsAtEmployer": 24, // Optional
          "annualIncome": "45000" // Optional, in dollars
        }
      ],
      "creditIndicator": "800" // Optional, a credit indicator
    }
  },
  // Required: At least one vehicle
  "vehicles": {
    "1": {
      // First vehicle is required
      "make": "Toyota",
      "model": "Camry",
      "year": "2020",
      // Optional fields below
      "vin": "1HGCM82633A123456", // Optional 
      "trim": "SE", // Optional
      "estimatedAnnualMileage": 12000, // Optional
      "isFinanced": true, // Optional
      // Optional
      "lien": {
        "lienHolder": "Bank of America", // Optional
        "monthlyPayment": "350", // Optional, in dollars
        "originalAmount": "25000", // Optional, in dollars
        "payoffAmount": "15000", // Optional, in dollars
        "remainingTerm": 36 // Optional, in months
      }
    },
    "2": {
      // Optional additional vehicles (keys 2-9). Optionality rules same as above
      "make": "Honda",
      "model": "CR-V",
      "year": "2019",
      "vin": "5J6RW2H89KL001234"
    }
  },
  "partnerBrand": "Blinker", // Optional. Used to show a brand to customers.
  // Optional: Used to pass miscellaneous data that doesn't fit into other fields
  "partnerData": {
    "sourceSystem": "PartnerPortal",
    "campaignId": "SPRING2024"
  },
  "isTest": false // Optional: Flag for test requests
}

 ```
